"#!/bin/bash\n# Apply critical code review fixes\n\nset -e  # Beende bei Fehlern\n\necho \"=== CODE REVIEW FIXES - 2025-01-18 ===\"\necho \"\"\n\n# Backup erstellen\necho \"[1/5] Creating backup...\"\nBACKUP_DIR=\".backup-$(date +%Y%m%d-%H%M%S)\"\nmkdir -p \"$BACKUP_DIR\"\ncp eslint.config.mjs \"$BACKUP_DIR/\"\ncp tsconfig.json \"$BACKUP_DIR/\"\necho \"Backup created at: $BACKUP_DIR\"\necho \"\"\n\n# ESLint Config ersetzen\necho \"[2/5] Updating ESLint config...\"\ncat > eslint.config.mjs << 'EOF'\nimport nextCoreWebVitals from \"eslint-config-next/core-web-vitals\";\nimport nextTypescript from \"eslint-config-next/typescript\";\nimport { dirname } from \"path\";\nimport { fileURLToPath } from \"url\";\n\nconst __filename = fileURLToPath(import.meta.url);\nconst __dirname = dirname(__filename);\n\nconst eslintConfig = [\n  ...nextCoreWebVitals,\n  ...nextTypescript,\n  {\n    rules: {\n      // TypeScript Rules - STRICT MODE\n      \"@typescript-eslint/no-explicit-any\": \"error\",\n      \"@typescript-eslint/no-unused-vars\": [\"warn\", {\n        argsIgnorePattern: \"^_\",\n        varsIgnorePattern: \"^_\",\n      }],\n      \"@typescript-eslint/no-non-null-assertion\": \"warn\",\n      \"@typescript-eslint/ban-ts-comment\": [\"warn\", {\n        \"ts-ignore\": \"allow-with-description\",\n        \"ts-nocheck\": true\n      }],\n      \"@typescript-eslint/consistent-type-imports\": [\"warn\", {\n        prefer: \"type-imports\",\n        disallowTypeAnnotations: false,\n      }],\n      \"@typescript-eslint/naming-convention\": [\n        \"warn\",\n        {\n          selector: \"interface\",\n          format: [\"PascalCase\"],\n          custom: {\n            regex: \"^I[A-Z]\",\n            match: false\n          }\n        }\n      ],\n      \n      // React Rules\n      \"react-hooks/exhaustive-deps\": \"warn\",\n      \"react-hooks/rules-of-hooks\": \"error\",\n      \"react/react-in-jsx-scope\": \"off\", // Next.js doesn't need React import\n      \"react/prop-types\": \"off\", // Using TypeScript instead\n      \"react/display-name\": \"off\",\n      \"react/no-unescaped-entities\": \"warn\",\n      \"no-console\": [\"warn\", { allow: [\"warn\", \"error\"] }],\n      \n      // Next.js Rules\n      \"@next/next/no-img-element\": \"warn\",\n      \"@next/next/no-html-link-for-pages\": \"warn\",\n      \n      // General Rules\n      \"prefer-const\": \"warn\",\n      \"no-var\": \"error\",\n      \"eqeqeq\": [\"error\", \"always\"],\n      \"curly\": [\"error\", \"all\"],\n      \"no-throw-literal\": \"error\",\n    },\n  },\n  {\n    ignores: [\n      \"node_modules/**\", \n      \".next/**\", \n      \"out/**\", \n      \"build/**\", \n      \"next-env.d.ts\", \n      \"examples/**\",\n      \"skills\",\n      \"*.config.js\",\n      \"*.config.mjs\",\n    ]\n  }\n];\n\nexport default eslintConfig;\nEOF\necho \"ESLint config updated.\"\necho \"\"\n\n# TypeScript Config patchen (mit jq, falls vorhanden, sonst sed)\necho -e \"[3/5] Updating TypeScript config...\"\nif command -v jq &> /dev/null; then\n    # JSON patch mit jq\n    jq '.compilerOptions.noImplicitAny = true |\n        .compilerOptions.noImplicitReturns = true |\n        .compilerOptions.noUnusedLocals = true |\n        .compilerOptions.noUnusedParameters = true |\n        .compilerOptions.noFallthroughCasesInSwitch = true |\n        .compilerOptions.target = \"ES2022\"' tsconfig.json > tsconfig.json.tmp\n    mv tsconfig.json.tmp tsconfig.json\nelse\n    # Fallback: Manual replacement mit sed (VORSICHTIGE Änderungen)\n    sed -i 's/|\"noImplicitAny\": false|/\\\"noImplicitAny\\\": true/g' tsconfig.json\n    echo \"  Using sed fallback (some changes may be incomplete). Install jq for better JSON editing.\"\nfi\necho \"TypeScript config updated.\"\necho \"\"\n\n# Typos korrigieren - PlayerProfile.tsx\necho \"[4/5] Fixing German typos in PlayerProfile component...\"\nif [ -f \"src/components/profile/PlayerProfile.tsx\" ]; then\n    # Backup vor Modification\n    cp src/components/profile/PlayerProfile.tsx \"$BACKUP_DIR/PlayerProfile.tsx.backup\"\n    \n    # Führe Korrekturen durch\n    sed -i 's/Wird abgebrochen\\.\\.\\./Wird abgebrochen.../g' src/components/profile/PlayerProfile.tsx\n    sed -i 's/Wird abgebrochen/Wird abgebrochen/g' src/components/profile/PlayerProfile.tsx\n    sed -i 's/Wird gesendet\\.\\.\\./Wird gesendet.../g' src/components/profile/PlayerProfile.tsx\n    sed -i 's/Wird gesendet/Wird gesendet/g' src/components/profile/PlayerProfile.tsx\n    sed -i 's/Freund hinzufgen/Freund hinzufügen/g' src/components/profile/PlayerProfile.tsx\n    \n    echo \"Typos fixed.\"\nelse\n    echo \"WARNING: PlayerProfile.tsx not found. Skipping typo fixes.\"\nfi\necho \"\"\n\n# Debug-Logs vorläufig_commentieren mit grep & sed\necho \"[5/5] Commenting out debug logs (safe mode)...\"\nFILES_WITH_LOGS=(\n    \"src/app/api/players/[id]/route.ts\"\n    \"src/components/profile/PlayerProfile.tsx\"\n)\n\nfor file in \"${FILES_WITH_LOGS[@]}\"; do\n    if [ -f \"$file\" ]; then\n        cp \"$file\" \"$BACKUP_DIR/$(basename $file).log-backup\"\n        # Safe: nur lines mit [Debug] oder [API] prefix kommentieren\n        sed -i 's|^\\(.*console\\.log(\\\"\[\\(Debug\\|API\\|PlayerProfile\\)\\)|\\n// DEBUG: \\1|g' \"$file\"\n        echo \" - Processed: $file\"\n    fi\ndone\necho \"\"\n\necho \"=== DONE ===\"\necho \"\"\necho \"Next steps:\"\necho \"1. Check the git diff: git diff\"\necho \"2. Review the changes before committing\"\necho \"3. Run: npm run lint (may show many warnings now - that's good!)\"\necho \"4. Test the application\"\necho \"\"\necho \"Backup location: $BACKUP_DIR\"\n\nexit 0"